function insRow2()
{
var description = new Array();
description[0] = "<tbody><tr><td><p>- En relaci&oacute;n con las definici&oacute;n establecidas en este inciso, se debe tener en cuenta lo dispuesto por el par&aacute;grafo del art&iacute;culo <A href='ley_1306_2009_pr001.html#53' >53</A> de la ley 1306 de 2009, el cual establece:</p><p><span class='i_aj'>&#160;'ART&Iacute;CULO <A href='ley_1306_2009_pr001.html#53' >53</A>....</span></p><p><span class='i_aj'>'PAR&Aacute;GRAFO. &#160;Para todos los efectos legales el imp&uacute;ber se equipara al ni&ntilde;o y ni&ntilde;a definido en el art&iacute;culo <A href='ley_1098_2006.html#3' >3</A>o del C&oacute;digo de la Infancia y Adolescencia. De igual manera, el menor adulto se equipara al adolescente de ese estatuto.</span></p><p><span class='i_aj'>'Con todo, la edad m&iacute;nima para contraer matrimonio se mantiene en 14 a&ntilde;os, tanto para los varones como para las mujeres.'</span></p><p>- La definici&oacute;n que para ni&ntilde;o o ni&ntilde;a define el art&iacute;culo <A href='ley_1098_2006.html#3' >3</A> (parcial) del C&oacute;digo de la Infancia y la Adolescencia es el siguiente:</p><p><span class='i_aj'>'ART&Iacute;CULO 3. &#160;&#160;.... Sin perjuicio de lo establecido en el art&iacute;culo <A href='codigo_civil_pr001.html#34' >34</A> del C&oacute;digo Civil, se entiende por ni&ntilde;o o ni&ntilde;a las personas entre los 0 y los 12 a&ntilde;os, y por adolescente las personas entre 12 y 18 a&ntilde;os de edad.'</span></p> </td></tr></tbody>";
var z=document.getElementById('Table2').rows[0];
if (z==null) {
              var x=document.getElementById('Table2').insertRow(0)
              var y=x.insertCell(0)
              y.innerHTML=description
             }
else         {
              document.getElementById('Table2').deleteRow(0)
             }
}
